#include <stdio.h>
int main(void){
    int nA=4, nB=3, nC=3;      /* |A|=4 {1,2,3,4}, |B|=3 {3,4,5}, |C|=3 {4,5,6} */
    int AB=2, AC=1, BC=2, ABC=1; /* 两两交与三交的大小（手算）*/
    int uni = nA + nB + nC - AB - AC - BC + ABC;
    printf("|A|=%d |B|=%d |C|=%d\n", nA, nB, nC);
    printf("|A∩B|=%d |A∩C|=%d |B∩C|=%d |A∩B∩C|=%d\n", AB, AC, BC, ABC);
    printf("|A∪B∪C| = %d (枚举验证: 1,2,3,4,5,6 共 6 个)\n", uni);
    return 0;
}
